mapper.select:
SELECT 
FROM posts p
JOIN users u ON u.id = p.user_id
WHERE p.id < #{beforeId}
ORDER BY p.id DESC
LIMIT #{limit}

SELECT 
FROM posts p
JOIN users u ON u.id = p.user_id
WHERE p.id > #{afterId}
ORDER BY p.id ASC
LIMIT #{limit}

SELECT id, user_id, content, created_at, updated_at
FROM posts
WHERE id = #{id}

mapper.update:
UPDATE posts
SET content = #{content}, updated_at = now()
WHERE id = #{id} AND user_id = #{userId}
